const fs = require('fs');
const initSqlJs = require('/home/node/.n8n/nodes/node_modules/sql.js');
const DB_PATH = '/home/node/.n8n/assistant.db';

const SQL = await initSqlJs();
const db = new SQL.Database(fs.readFileSync(DB_PATH));

// 1. Tasks
const high = db.exec("SELECT id, title, due_date FROM tasks WHERE status='pending' AND priority='high' LIMIT 5");
const medium = db.exec("SELECT id, title, due_date FROM tasks WHERE status='pending' AND priority='medium' LIMIT 5");
const overdue = db.exec("SELECT id, title, due_date FROM tasks WHERE status='pending' AND due_date < date('now') AND due_date IS NOT NULL");

// 2. Projects
const projects = db.exec("SELECT name, status, last_updated FROM projects WHERE status='active'");

// 3. Events for today
const events = db.exec("SELECT title, start_time, end_time, location FROM events WHERE DATE(start_time) = DATE('now', 'localtime') ORDER BY start_time");

// 4. Habits & streaks
let habits = [];
try {
  const r = db.exec("SELECT name, current_streak, best_streak, target_frequency FROM habits WHERE is_active = 1");
  habits = r[0]?.values.map(row => ({name: row[0], streak: row[1], best: row[2], target: row[3]})) || [];
} catch(e) {}

// 5. Commitments approaching deadline
let commitments = [];
try {
  const r = db.exec("SELECT description, deadline, related_project FROM commitments WHERE status = 'active' AND deadline IS NOT NULL ORDER BY deadline ASC LIMIT 5");
  commitments = r[0]?.values.map(row => ({description: row[0], deadline: row[1], project: row[2]})) || [];
} catch(e) {}

// 6. Recent conversation summaries
let recentSummaries = [];
try {
  const r = db.exec("SELECT summary, mood FROM conversation_summaries ORDER BY created_at DESC LIMIT 3");
  recentSummaries = r[0]?.values.map(row => ({summary: row[0], mood: row[1]})) || [];
} catch(e) {}

// 7. Active topics
let activeTopics = [];
try {
  const r = db.exec("SELECT topic, summary, related_project FROM active_topics WHERE status = 'open' ORDER BY last_mentioned DESC LIMIT 5");
  activeTopics = r[0]?.values.map(row => ({topic: row[0], summary: row[1], project: row[2]})) || [];
} catch(e) {}

// 8. Contacts needing follow-up
let staleContacts = [];
try {
  const r = db.exec("SELECT name, last_interaction, role, context FROM contacts WHERE last_interaction < datetime('now', '-14 days') OR last_interaction IS NULL ORDER BY last_interaction ASC LIMIT 5");
  staleContacts = r[0]?.values.map(row => ({name: row[0], lastSeen: row[1], role: row[2], context: row[3]})) || [];
} catch(e) {}

// 9. Spending this week
let weeklySpend = 0;
let topCategory = '';
try {
  const r = db.exec("SELECT SUM(amount), category FROM expenses WHERE logged_at >= date('now', '-7 days') GROUP BY category ORDER BY SUM(amount) DESC LIMIT 1");
  if (r[0]?.values.length) { weeklySpend = r[0].values[0][0] || 0; topCategory = r[0].values[0][1] || ''; }
} catch(e) {}

// 10. Recent knowledge additions
let recentKB = [];
try {
  const r = db.exec("SELECT title, category, summary FROM knowledge_base WHERE created_at >= datetime('now', '-7 days') ORDER BY created_at DESC LIMIT 5");
  recentKB = r[0]?.values.map(row => ({title: row[0], category: row[1], summary: row[2]})) || [];
} catch(e) {}

// 11. Ideas count
let ideaCount = 0;
try {
  const r = db.exec("SELECT COUNT(*) FROM ideas WHERE status = 'incubating'");
  ideaCount = r[0]?.values[0][0] || 0;
} catch(e) {}

// 12. Pending tasks count
let pendingCount = 0;
try {
  const r = db.exec("SELECT COUNT(*) FROM tasks WHERE status = 'pending'");
  pendingCount = r[0]?.values[0][0] || 0;
} catch(e) {}

db.close();

// Load vault context
const context = fs.existsSync('/vault/AI Memory/context/current.md')
  ? fs.readFileSync('/vault/AI Memory/context/current.md', 'utf8')
  : '';

return [{
  json: {
    high_priority: high[0]?.values.map(r => ({id: r[0], title: r[1], due: r[2]})) || [],
    medium_priority: medium[0]?.values.map(r => ({id: r[0], title: r[1], due: r[2]})) || [],
    overdue: overdue[0]?.values.map(r => ({id: r[0], title: r[1], due: r[2]})) || [],
    active_projects: projects[0]?.values.map(r => ({name: r[0], status: r[1], updated: r[2]})) || [],
    events_today: events[0]?.values.map(r => ({title: r[0], start: r[1], end: r[2], location: r[3]})) || [],
    habits: habits,
    commitments: commitments,
    recent_summaries: recentSummaries,
    active_topics: activeTopics,
    stale_contacts: staleContacts,
    weekly_spend: weeklySpend,
    top_spend_category: topCategory,
    recent_kb: recentKB,
    idea_count: ideaCount,
    pending_tasks: pendingCount,
    weekly_context: context,
    chat_id: $env.TELEGRAM_CHAT_ID,
    date: new Date().toLocaleDateString('en-KE', {weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Africa/Nairobi'}),
    greeting: getGreeting()
  }
}];

function getGreeting() {
  const hour = Number(new Intl.DateTimeFormat('en-KE', {hour: 'numeric', hourCycle: 'h23', timeZone: 'Africa/Nairobi'}).format(new Date()));
  if (hour < 12) return 'Good morning';
  if (hour < 17) return 'Good afternoon';
  return 'Good evening';
}

